// app/posts/[id]/page.tsx — Server Component mặc định
import 'server-only';
import { Suspense } from 'react';
import { notFound } from 'next/navigation';
import { db } from '@/lib/db';
import { renderAndSanitizeMarkdown } from '@/lib/markdown.server';
import { LikeButton } from './like-button';

type PageProps = { params: Promise<{ id: string }> };

async function PostBody({ id }: { id: string }) {
  const post = await db.post.findUnique({
    where: { id },
    select: { id: true, title: true, body: true, likes: true },
  });
  if (!post) notFound();

  const safeHtml = renderAndSanitizeMarkdown(post.body);
  return (
    <article>
      <h1>{post.title}</h1>
      <div dangerouslySetInnerHTML={{ __html: safeHtml }} />
      {/* Chỉ primitive data cần thiết đi qua client boundary. */}
      <LikeButton postId={post.id} initialLikes={post.likes} />
    </article>
  );
}

export default async function PostPage({ params }: PageProps) {
  const { id } = await params;
  return (
    <Suspense fallback={<PostSkeleton />}>
      <PostBody id={id} />
    </Suspense>
  );
}

