// app/products/[category]/[id]/page.tsx (Next.js 15+)
import { cookies } from 'next/headers';
import { Suspense } from 'react';

type PageProps = {
  params: Promise<{ category: string; id: string }>;
  searchParams: Promise<{ [key: string]: string | string[] | undefined }>;
};

export default async function ProductPage({ params, searchParams }: PageProps) {
  // 1. Await params và searchParams bất đồng bộ
  const { category, id } = await params;
  const query = await searchParams;

  // 2. Await cookies và headers
  const cookieStore = await cookies();
  const token = cookieStore.get('auth_token')?.value;

  return (
    <div>
      <h1>Category: {category} | Product: {id}</h1>
      <p>Affiliate Source: {query.ref ?? 'direct'}</p>
      <p>Logged In: {token ? 'Yes' : 'No'}</p>
    </div>
  );
}

