import 'server-only';
import { experimental_taintObjectReference, experimental_taintUniqueValue } from 'react';
import { db } from '@/lib/db';

export async function getUserById(id: string) {
  const user = await db.user.findUnique({ where: { id } });
  if (!user) return null;

  // 1. Khóa toàn bộ object user nhạy cảm
  experimental_taintObjectReference(
    'Không được truyền trực tiếp raw user object xuống Client Component! Dùng DTO.',
    user
  );

  // 2. Khóa token thanh toán nhạy cảm nếu có
  if (user.stripeSecretToken) {
    experimental_taintUniqueValue(
      'Không bao giờ được leak stripe token xuống browser!',
      user,
      user.stripeSecretToken
    );
  }

  return user;
}

