// middleware.ts
import { NextRequest, NextResponse } from 'next/server';
import { getTenantFromHost } from '@/lib/tenant-resolver.edge';

export const config = {
  matcher: ['/((?!api/|_next/|_static/|_vercel|[\\w-]+\\.\\w+).*)'],
};

export async function middleware(request: NextRequest) {
  const url = request.nextUrl;
  const hostname = request.headers.get('host') || '';

  // 1. Phân giải tenant từ subdomain hoặc custom domain
  const tenant = await getTenantFromHost(hostname);
  if (!tenant) {
    return NextResponse.redirect(new URL('https://platform.com/not-found', request.url));
  }

  // 2. Rewrite ngầm tới dynamic route app/[tenant]/...
  const rewriteUrl = new URL(`/${tenant.slug}${url.pathname}${url.search}`, request.url);

  const response = NextResponse.rewrite(rewriteUrl);
  // 3. Gắn header tenant an toàn cho Server Components tiêu thụ
  response.headers.set('x-tenant-id', tenant.id);
  response.headers.set('x-tenant-slug', tenant.slug);

  return response;
}

// app/[tenant]/page.tsx
import { headers } from 'next/headers';
import { db } from '@/lib/db';

export default async function TenantHomePage({
  params,
}: { params: Promise<{ tenant: string }> }) {
  const { tenant } = await params;
  const headersList = await headers();
  const tenantId = headersList.get('x-tenant-id');

  // Query đảm bảo tuyệt đối cách ly dữ liệu
  const products = await db.product.findMany({
    where: { tenantId: tenantId! },
  });

  return <div>Tenant: {tenant} - {products.length} products</div>;
}
